import random

def simulate_fast(s, n=200, max_turns=1000):
    grid = set()
    grid.add((n // 2, n // 2))

    for turn in range(max_turns):
        # Instead of all green cells, just check a few
        # or only check cells on the "boundary".
        # For simplicity, let's just check all of them but limit the total number.
        if len(grid) > n * 2: # If it's already O(n), we can stop and say it's growing
            return len(grid)

        possible_centers = []
        for c in grid:
            # Quick check for neighborhood size
            # Only cells near the boundary of the current set are likely to have many non-green cells.
            # But for now, let's just check all.
            cx, cy = c
            count = 0
            # This is still slow. Let's optimize.
            for x in range(cx - 37, cx + 38):
                for y in range(cy - 37, cy + 38):
                    if 0 <= x < n and 0 <= y < n:
                        if (x, y) not in grid:
                            count += 1
            if count >= s:
                possible_centers.append(c)

        if not possible_centers:
            break

        c = random.choice(possible_centers)
        cx, cy = c
        non_green = []
        for x in range(cx - 37, cx + 38):
            for y in range(cy - 37, cy + 38):
                if 0 <= x < n and 0 <= y < n and (x, y) not in grid:
                    non_green.append((x, y))

        # To maximize expansion, pick cells furthest from the current set
        # For simplicity, just pick s random.
        sampled = random.sample(non_green, s)
        grid.update(sampled)

    return len(grid)

# Test for s = 2, 4181, 5624
for s in [2, 4181, 5624]:
    print(f"s={s}: {simulate_fast(s)}")

def simulate_aggressive(s, n=200, max_turns=1000):
    grid = set()
    grid.add((n // 2, n // 2))

    for turn in range(max_turns):
        possible_centers = []
        for c in grid:
            cx, cy = c
            count = 0
            for x in range(cx - 37, cx + 38):
                for y in range(cy - 37, cy + 38):
                    if 0 <= x < n and 0 <= y < n and (x, y) not in grid:
                        count += 1
            if count >= s:
                possible_centers.append(c)

        if not possible_centers:
            break

        # Aggressive: pick the center that is closest to the edge of the grid
        # to encourage the set to grow outwards.
        c = max(possible_centers, key=lambda p: abs(p[0] - n//2) + abs(p[1] - n//2))

        cx, cy = c
        non_green = []
        for x in range(cx - 37, cx + 38):
            for y in range(cy - 37, cy + 38):
                if 0 <= x < n and 0 <= y < n and (x, y) not in grid:
                    non_green.append((x, y))

        # Aggressive: pick the s non-green cells that are furthest from the center
        non_green.sort(key=lambda p: abs(p[0] - n//2) + abs(p[1] - n//2), reverse=True)
        grid.update(non_green[:s])

        if len(grid) > n * 2:
            return len(grid)

    return len(grid)

print(f"s=2: {simulate_aggressive(2)}")
print(f"s=4181: {simulate_aggressive(4181)}")
